    setWireframe(wireframe: boolean): void;
    /**
     * 도형을 와이어프레임(wireframe)으로 그리고 있는지 반환합니다.
     *
     * @returns {boolean} 삼각형 모서리만 선으로 그리고 있으면 `true`, 면을 채워 그리고 있으면 `false`
     */
    getWireframe(): boolean;
