    checkGeom(scene: three.Object3D | three.Group | three.Scene | UMesh, geom: OLGeometry): Array<{
        object: any;
        geom: OLGeometry;
    } & Partial<{
        instanceId: number;
    }>>;
    _measureGeom: any;
